"""Generated by deploy/build_bundle.py from contracts/metering.py and contracts/meter.py.
Comments removed to keep the deploy small; read them in those files."""
UP = 'up'
DOWN = 'down'
OUTCOMES = (UP, DOWN)
MIN_SAMPLES = 3
SLOT_SECONDS = 600
READ_WITHIN = 240
MIN_WINDOW = 3600
MAX_WINDOW = 31 * 24 * 3600
FULL = 10000
_MAX_PATH = 120
_MAX_MARKER = 80

def valid_host(host: str) -> bool:
    h = (host or '').strip().lower()
    if not h or len(h) > 100 or h.startswith('.') or h.endswith('.') or ('..' in h):
        return False
    for ch in h:
        if not ('0' <= ch <= '9' or 'a' <= ch <= 'z' or ch in '-.'):
            return False
    return '.' in h

def valid_path(path: str) -> bool:
    p = (path or '').strip()
    if not p.startswith('/') or len(p) > _MAX_PATH:
        return False
    if '..' in p or '://' in p or '?' in p or ('#' in p) or ('//' in p):
        return False
    for ch in p:
        if ch <= ' ' or ch == '\x7f':
            return False
    return True

def valid_marker(marker: str) -> bool:
    m = (marker or '').strip()
    return bool(m) and len(m) <= _MAX_MARKER and ('\n' not in m) and ('\r' not in m)

def url_for(host: str, path: str) -> str:
    return 'https://' + host.strip().lower() + path.strip()

def classify(status: int, body: str, marker: str) -> dict:
    code = int(status)
    if 200 <= code < 300:
        if marker.strip() in (body or ''):
            return {'outcome': UP, 'note': 'answered with the marker'}
        return {'outcome': DOWN, 'note': 'answered without the marker'}
    return {'outcome': DOWN, 'note': 'answered ' + str(code)}

def unreached() -> dict:
    return {'outcome': DOWN, 'note': 'could not be reached'}

def slot_count(opens: int, ends: int) -> int:
    if opens < 0 or ends <= opens:
        return 0
    return (int(ends) - int(opens)) // SLOT_SECONDS

def slot_at(opens: int, ends: int, now: int) -> int:
    if opens < 0 or now < opens or now >= ends:
        return -1
    k = (int(now) - int(opens)) // SLOT_SECONDS
    if k >= slot_count(opens, ends):
        return -1
    if int(now) - (int(opens) + k * SLOT_SECONDS) >= READ_WITHIN:
        return -1
    return k

def uptime_bp(up: int, slots: int) -> int:
    if slots <= 0:
        return 0
    return int(up) * FULL // int(slots)

def share(fee: int, up: int, taken: int, slots: int) -> dict:
    total = int(fee)
    up_n = int(up)
    read = int(taken)
    n = int(slots)
    if total < 0 or up_n < 0 or read < 0 or (up_n > read) or (read > n):
        raise ValueError('an impossible tally')
    if read < MIN_SAMPLES:
        return {'provider': 0, 'buyer': total, 'billed': False}
    provider = total * up_n // n
    return {'provider': provider, 'buyer': total - provider, 'billed': True}

def epoch_seconds(stamp: str):
    s = (stamp or '').strip()
    if len(s) < 19 or s[4] != '-' or s[7] != '-' or (s[10] != 'T') or (s[13] != ':') or (s[16] != ':'):
        return None
    for i in (0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15, 17, 18):
        if not '0' <= s[i] <= '9':
            return None
    year, month, day = (int(s[0:4]), int(s[5:7]), int(s[8:10]))
    hour, minute, second = (int(s[11:13]), int(s[14:16]), int(s[17:19]))
    if not 1 <= month <= 12 or day < 1 or day > _days_in_month(year, month):
        return None
    if hour > 23 or minute > 59 or second > 60:
        return None
    return _days_from_civil(year, month, day) * 86400 + hour * 3600 + minute * 60 + second

def _days_in_month(year: int, month: int) -> int:
    if month == 2:
        leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
        return 29 if leap else 28
    return 30 if month in (4, 6, 9, 11) else 31

def _days_from_civil(year: int, month: int, day: int) -> int:
    y = year - (1 if month <= 2 else 0)
    era = (y if y >= 0 else y - 399) // 400
    year_of_era = y - era * 400
    day_of_year = (153 * (month + (-3 if month > 2 else 9)) + 2) // 5 + day - 1
    day_of_era = year_of_era * 365 + year_of_era // 4 - year_of_era // 100 + day_of_year
    return era * 146097 + day_of_era - 719468
from dataclasses import dataclass
import genlayer as gl
from genlayer.types import *

@gl.storage.allow
@dataclass
class Reading:
    at: str
    slot: u256
    outcome: str

@gl.storage.allow
@dataclass
class Tally:
    up: u256
    down: u256
    last_at: str

class Meter(gl.contract.Contract):
    plan: Address
    tallies: gl.storage.TreeMap[str, Tally]
    readings: gl.storage.TreeMap[str, gl.storage.DynArray[Reading]]
    taken: gl.storage.TreeMap[str, bool]

    def __init__(self, plan: str):
        self.plan = _address(plan)

    @gl.public.write
    def sample(self, plan_id: str) -> dict:
        key = plan_id.strip().lower()
        terms = gl.contract.get_at(self.plan).view().get(key)
        if str(terms['plan_id']).lower() != key:
            raise gl.vm.UserError('those terms are about a different plan')
        if str(terms['state']) != 'live':
            raise gl.vm.UserError('that plan is ' + str(terms['state']) + ', not live')
        now = epoch_seconds(_stamp())
        if now is None:
            raise gl.vm.UserError('the clock could not be read')
        opens = int(str(terms['opens_at']))
        ends = int(str(terms['ends_at']))
        if opens < 0 or now < opens:
            raise gl.vm.UserError('the window has not opened')
        if now >= ends:
            raise gl.vm.UserError('the window has closed')
        slot = slot_at(opens, ends, now)
        if slot < 0:
            raise gl.vm.UserError(f'a reading counts only in the first {READ_WITHIN} seconds of each {SLOT_SECONDS}-second slot')
        slot_key = key + '#' + str(slot)
        if slot_key in self.taken:
            raise gl.vm.UserError(f'slot {slot} already has its reading')
        tally = self.tallies[key] if key in self.tallies else Tally(up=0, down=0, last_at='')
        url = url_for(str(terms['host']), str(terms['path']))
        marker = str(terms['marker'])

        def leader_fn():
            return _read(url, marker)

        def validator_fn(leaders_res) -> bool:
            if not isinstance(leaders_res, gl.vm.Return):
                return False
            leader = leaders_res.calldata
            if not isinstance(leader, dict):
                return False
            return leader.get('outcome') == _read(url, marker)['outcome']
        agreed = gl.vm.run_nondet(leader_fn, validator_fn)
        outcome = str(agreed['outcome'])
        if outcome not in OUTCOMES:
            raise gl.vm.UserError('a reading no fetch could produce')
        stamp = _stamp()
        if outcome == UP:
            tally.up = tally.up + 1
        else:
            tally.down = tally.down + 1
        tally.last_at = stamp
        self.tallies[key] = tally
        self.taken[slot_key] = True
        self.readings.get_or_insert_default(key).append(Reading(at=stamp, slot=slot, outcome=outcome))
        return _tally_dict(key, tally, opens, ends, now)

    @gl.public.view
    def tally(self, plan_id: str) -> dict:
        key = plan_id.strip().lower()
        terms = gl.contract.get_at(self.plan).view().get(key)
        opens = int(str(terms['opens_at']))
        ends = int(str(terms['ends_at']))
        tally = self.tallies[key] if key in self.tallies else Tally(up=0, down=0, last_at='')
        return _tally_dict(key, tally, opens, ends, epoch_seconds(_stamp()))

    @gl.public.view
    def samples(self, plan_id: str) -> list:
        key = plan_id.strip().lower()
        if key not in self.readings:
            return []
        return [{'at': r.at, 'slot': str(r.slot), 'outcome': r.outcome} for r in self.readings[key]]

    @gl.public.view
    def settings(self) -> dict:
        return {'plan': self.plan.as_hex, 'slot_seconds': str(SLOT_SECONDS), 'read_within_seconds': str(READ_WITHIN), 'min_samples': str(MIN_SAMPLES)}

def _read(url: str, marker: str) -> dict:
    try:
        resp = gl.nondet.web.get(url)
        status = int(resp.status)
        body = (resp.body or b'').decode('utf-8', errors='replace')
    except Exception:
        return {'outcome': unreached()['outcome']}
    return {'outcome': classify(status, body, marker)['outcome']}

def _stamp() -> str:
    return str(gl.message.raw['datetime'])

def _address(value) -> Address:
    if hasattr(value, 'as_hex'):
        return value
    return Address(str(value).strip())

def _tally_dict(key: str, tally: Tally, opens: int, ends: int, now) -> dict:
    up = int(tally.up)
    down = int(tally.down)
    taken = up + down
    slots = slot_count(opens, ends)
    closed = ends >= 0 and now is not None and (now >= ends)
    return {'plan_id': key, 'up': str(up), 'down': str(down), 'samples': str(taken), 'slots': str(slots), 'uptime_bp': str(uptime_bp(up, slots)), 'enough': taken >= MIN_SAMPLES, 'closed': closed, 'last_at': tally.last_at}
